function Menu(){
    return(
        <div>
            <nav>
                <Link to="/">Inicio</Link><tr></tr>
                <Link to="/Verincidencias">Ver incidencias</Link><tr></tr>
                <Link to="/Registrarincidencias">Registrar incidencias</Link>
                <Link to="/Gestionusuarios">Gestion usuarios</Link>
            </nav>
        </div>
    );
}
export default Menu;
